 			records[i] = stackitdnsclient.RecordPayload{
 				Content: record.Content,
 			}
 		}
 	}
 	payload := stackitdnsclient.CreateRecordSetPayload{
 		Comment: rrSet.Comment,
 		Name:    rrSet.Name,
 		Ttl:     rrSet.Ttl,
 		Type:    rrSet.Type,
 		Records: &records,
 	}
