 	if err != nil {
 		return err
 	}

 	return nil
 }

 func (r *rrSetRepository) UpdateRRSet(
 	ctx context.Context,
 	rrSet stackitdnsclient.RecordSet,
 ) error {
 	records := make([]stackitdnsclient.RecordPayload, len(*rrSet.Records))
 	for i, record := range *rrSet.Records {
 		records[i] = stackitdnsclient.RecordPayload{
