 		var oapiError *oapierror.GenericOpenAPIError
 		if errors.As(err, &oapiError) {
 			if oapiError.StatusCode == 404 || oapiError.StatusCode == 400 {
 				return ErrRRSetNotFound
 			}
 		}
 	}

 	return err
 }

